import{a as e,i as t,r as n,s as r,t as i}from"./app-CchzzT6L.js";var a=JSON.parse(`{"path":"/youtube/go-garble.html","title":"Go Garble","lang":"en-US","frontmatter":{},"git":{"updatedTime":1748677577000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"1befd4062c8715aa2a74f4a8c539ca927fc7fae2","time":1748677577000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add youtube content"}]},"filePathRelative":"youtube/go-garble.md"}`),o={name:`go-garble.md`};function s(i,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[n(`h1`,{id:`go-garble`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#go-garble`},[n(`span`,null,`Go Garble`)])],-1),n(`iframe`,{width:`100%`,height:`500`,src:`https://www.youtube.com/embed/gewnAzaZXQo`,title:`golang obfuscated malware goes crazy`,frameborder:`0`,allow:`accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share`,referrerpolicy:`strict-origin-when-cross-origin`,allowfullscreen:``},null,-1),e(`<h3 id="ภาพรวมเนื้อหา" tabindex="-1"><a class="header-anchor" href="#ภาพรวมเนื้อหา"><span>ภาพรวมเนื้อหา</span></a></h3><p>คลิปวิดีโอนี้เปรียบเสมือนสนามประลองระหว่าง &quot;ผู้สร้างมัลแวร์&quot; และ &quot;นักวิเคราะห์ความปลอดภัย&quot; ในโลกของภาษาโปรแกรม Go (หรือ Golang) โดยจะแสดงให้เห็นว่าทำไมผู้พัฒนาโปรแกรมไม่พึงประสงค์ (มัลแวร์) ถึงนิยมใช้ภาษา Go มากขึ้น และในขณะเดียวกัน นักวิเคราะห์มีเครื่องมือและเทคนิคอะไรบ้างในการแกะรอยโปรแกรมเหล่านี้ ตั้งแต่การวิเคราะห์โปรแกรมแบบปกติ ไปจนถึงการรับมือกับโปรแกรมที่ถูก &quot;อำพรางโค้ด&quot; (Obfuscation) เพื่อให้ยากต่อการตรวจสอบ</p><h3 id="เนื้อหาในคลิปโดยละเอียด" tabindex="-1"><a class="header-anchor" href="#เนื้อหาในคลิปโดยละเอียด"><span>เนื้อหาในคลิปโดยละเอียด</span></a></h3><ol><li><p><strong>ทำไมภาษา Go ถึงเป็นที่นิยมในการสร้างมัลแวร์?</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=0" target="_blank" rel="noopener noreferrer">00:00</a>]</p><ul><li>วิดีโอเริ่มต้นด้วยการอธิบายข้อดีของภาษา Go เช่น การที่สามารถคอมไพล์ (compile) ครั้งเดียวแล้วนำไปรันได้หลายระบบปฏิบัติการ (cross-platform), ได้ไฟล์โปรแกรมที่พกพาสะดวก, โค้ดอ่านง่าย, มีระบบจัดการหน่วยความจำที่ปลอดภัย และยังสามารถทำงานในระดับลึก (low-level) ได้ ทำให้เหมาะกับการพัฒนาแอปพลิเคชันขนาดใหญ่ และในทางกลับกันก็เป็นที่นิยมในการสร้างมัลแวร์ด้วย</li></ul></li><li><p><strong>การวิเคราะห์โปรแกรม Go ทั่วไป (ที่ยังไม่ถูกอำพรางโค้ด)</strong></p><ul><li>ผู้จัดทำคลิปได้สร้างโปรเจกต์ &quot;มัลแวร์&quot; ปลอมๆ ขึ้นมาด้วยภาษา Go โดยมีฟังก์ชันง่ายๆ คือการพิมพ์ข้อความ &quot;Hello world&quot; และ &quot;please subscribe&quot; ซึ่งเป็น &quot;รหัสลับ&quot; ที่ซ่อนอยู่ [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=176" target="_blank" rel="noopener noreferrer">02:56</a>]</li><li>จากนั้น เขาได้คอมไพล์โปรแกรมออกมา 2 แบบ คือ <code>debug.exe</code> (มีข้อมูลสำหรับดีบักครบถ้วน) และ <code>release.exe</code> (พยายามลบข้อมูลที่ไม่จำเป็นออกไป) [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=239" target="_blank" rel="noopener noreferrer">03:59</a>]</li><li>เมื่อนำไฟล์ทั้งสองไปวิเคราะห์ด้วยเครื่องมือมาตรฐานอย่าง <strong>Binary Ninja, IDA, และ Ghidra</strong> ก็พบว่าถึงแม้จะเป็นเวอร์ชัน <code>release.exe</code> ที่พยายามลบข้อมูลแล้ว แต่ก็ยังสามารถค้นหาข้อความที่เป็น &quot;รหัสลับ&quot; (<code>please subscribe</code>) เจอได้ไม่ยาก และยังพอจะเห็นโครงสร้างของฟังก์ชันต่างๆ ได้อยู่ [00:07:30 - 00:10:09]</li><li>จากนั้นได้ลองใช้เครื่องมือที่สร้างมาเพื่อวิเคราะห์ภาษา Go โดยเฉพาะอย่าง <strong>Redress</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=653" target="_blank" rel="noopener noreferrer">10:53</a>] และ <strong>Go ReSim</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=854" target="_blank" rel="noopener noreferrer">14:14</a>] ซึ่งเครื่องมือเหล่านี้ช่วยดึงข้อมูลเชิงลึก เช่น เวอร์ชันของ Go ที่ใช้สร้างโปรแกรม, สถาปัตยกรรม, และข้อมูลโมดูลต่างๆ ได้ดีขึ้น แต่ก็ยังไม่สมบูรณ์แบบนักสำหรับไฟล์ที่ถูกลบข้อมูลไปแล้ว</li></ul></li><li><p><strong>การอำพรางโค้ด (Obfuscation) ด้วย Garble</strong></p><ul><li>จุดสำคัญของคลิปคือการแนะนำเครื่องมือชื่อ <strong>Garble</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1007" target="_blank" rel="noopener noreferrer">16:47</a>] ซึ่งเป็นเครื่องมือที่ผู้สร้างมัลแวร์ใช้เพื่อ &quot;ป่วน&quot; หรือ &quot;อำพราง&quot; โค้ดของโปรแกรมที่เขียนด้วย Go ทำให้การวิเคราะห์ทำได้ยากขึ้นอย่างมหาศาล</li><li>เมื่อนำโปรเจกต์มัลแวร์เดิมมาคอมไพล์ด้วย Garble จะได้ไฟล์ใหม่ชื่อ <code>garbled.exe</code> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1171" target="_blank" rel="noopener noreferrer">19:31</a>]</li><li>ผลลัพธ์คือ <strong>เครื่องมือวิเคราะห์ทั้งหมดที่เคยใช้ได้ผลก่อนหน้านี้ กลับแทบจะใช้งานไม่ได้เลย</strong> การค้นหาข้อความ &quot;รหัสลับ&quot; ไม่เจออีกต่อไป, ชื่อฟังก์ชันกลายเป็นตัวอักษรที่อ่านไม่รู้เรื่อง และโครงสร้างโปรแกรมก็ดูยุ่งเหยิงไปหมด [00:20:04 - 00:22:54]</li></ul></li><li><p><strong>การแกะรอยโปรแกรมที่ถูกอำพรางด้วย Garble</strong></p><ul><li>เมื่อฝ่ายแดง (ผู้สร้างมัลแวร์) มีเครื่องมืออำพราง ฝ่ายน้ำเงิน (นักวิเคราะห์) ก็มีเครื่องมือแกะรอยเช่นกัน วิดีโอได้แนะนำเครื่องมือสำคัญคือ <strong>Go String Ungarbler</strong> จากทีมงานของ Google Cloud และ Mandiant [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1491" target="_blank" rel="noopener noreferrer">24:51</a>]</li><li>เครื่องมือนี้ถูกออกแบบมาเพื่อ <strong>ถอดรหัสข้อความ (strings) ที่ถูกอำพรางโดย Garble โดยเฉพาะ</strong></li><li>ผลลัพธ์คือ Go String Ungarbler สามารถดึง &quot;รหัสลับ&quot; (<code>please subscribe</code>) ที่ซ่อนอยู่ออกมาจากไฟล์ <code>garbled.exe</code> ได้สำเร็จ ทั้งๆ ที่เครื่องมืออื่นก่อนหน้านี้ทำไม่สำเร็จ [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1695" target="_blank" rel="noopener noreferrer">28:15</a>]</li></ul></li><li><p><strong>เครื่องมืออื่นๆ และแหล่งข้อมูลเพิ่มเติม</strong></p><ul><li>วิดีโอได้แนะนำเครื่องมืออื่นๆ ที่น่าสนใจเพิ่มเติม เช่น <strong>Ungarble</strong> (ปลั๊กอินสำหรับโปรแกรม Binary Ninja เพื่อแกะรอยโปรแกรมที่ถูก Garble) [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1861" target="_blank" rel="noopener noreferrer">31:01</a>] และ <strong>Go Resolver</strong> (เครื่องมือแกะรอยอัตโนมัติสำหรับ IDA Pro และ Ghidra) [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1951" target="_blank" rel="noopener noreferrer">32:31</a>]</li></ul></li></ol><hr><h3 id="การสาธิต-demo-ที่แสดงในคลิป" tabindex="-1"><a class="header-anchor" href="#การสาธิต-demo-ที่แสดงในคลิป"><span>การสาธิต (Demo) ที่แสดงในคลิป</span></a></h3><p>ในคลิปมีการสาธิตการใช้งานเครื่องมือต่างๆ ให้ดูเป็นขั้นตอนอย่างชัดเจน ดังนี้ครับ</p><p><strong>Demo 1: การสร้างและวิเคราะห์โปรแกรม Go แบบปกติ</strong></p><ol><li><strong>สร้างโปรเจกต์:</strong> สร้างโปรแกรม Go ง่ายๆ ที่มี 2 ส่วน คือ <code>main.go</code> และ <code>secret.go</code> โดยให้ส่วน <code>secret</code> มีฟังก์ชันที่พิมพ์ข้อความ &quot;please subscribe&quot; [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=154" target="_blank" rel="noopener noreferrer">02:34</a>]</li><li><strong>คอมไพล์:</strong> คอมไพล์โปรแกรมออกมา 2 ไฟล์ คือ <code>debug.exe</code> และ <code>release.exe</code> (เวอร์ชันพยายามลบข้อมูล) [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=239" target="_blank" rel="noopener noreferrer">03:59</a>]</li><li><strong>วิเคราะห์ด้วยเครื่องมือทั่วไป:</strong> เปิดไฟล์ <code>debug.exe</code> และ <code>release.exe</code> ด้วยโปรแกรม <strong>Binary Ninja</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=450" target="_blank" rel="noopener noreferrer">07:30</a>], <strong>IDA</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=526" target="_blank" rel="noopener noreferrer">08:46</a>], และ <strong>Ghidra</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=579" target="_blank" rel="noopener noreferrer">09:39</a>] เพื่อแสดงให้เห็นว่า แม้จะเป็นเวอร์ชัน <code>release</code> ก็ยังสามารถค้นหาข้อความ &quot;please subscribe&quot; เจอได้ในส่วนของ strings</li><li><strong>วิเคราะห์ด้วยเครื่องมือเฉพาะทาง:</strong> รันโปรแกรม <strong>Redress</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=736" target="_blank" rel="noopener noreferrer">12:16</a>] และ <strong>Go ReSim</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=892" target="_blank" rel="noopener noreferrer">14:52</a>] กับไฟล์ <code>release.exe</code> เพื่อแสดงการดึงข้อมูลจำเพาะของภาษา Go เช่น Build ID และ Go version</li></ol><p><strong>Demo 2: การอำพรางโค้ดด้วย Garble และผลกระทบ</strong></p><ol><li><strong>ติดตั้ง Garble:</strong> แสดงคำสั่งติดตั้ง Garble ผ่าน command line [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1102" target="_blank" rel="noopener noreferrer">18:22</a>]</li><li><strong>คอมไพล์ด้วย Garble:</strong> ใช้คำสั่ง <code>garble build</code> กับโปรเจกต์เดิมเพื่อสร้างไฟล์ <code>garbled.exe</code> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1135" target="_blank" rel="noopener noreferrer">18:55</a>]</li><li><strong>เปรียบเทียบผล:</strong> ใช้คำสั่ง <code>strings</code> ง่ายๆ กับไฟล์ <code>release.exe</code> และ <code>garbled.exe</code> เพื่อแสดงให้เห็นว่าไฟล์ที่ผ่าน Garble มาแล้ว จะไม่แสดงข้อความ &quot;please subscribe&quot; อีกต่อไป [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1204" target="_blank" rel="noopener noreferrer">20:04</a>]</li><li><strong>ทดสอบกับเครื่องมือวิเคราะห์:</strong> เปิดไฟล์ <code>garbled.exe</code> ด้วย <strong>Binary Ninja</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1224" target="_blank" rel="noopener noreferrer">20:24</a>], <strong>IDA</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1246" target="_blank" rel="noopener noreferrer">20:46</a>], และ <strong>Ghidra</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1277" target="_blank" rel="noopener noreferrer">21:17</a>] อีกครั้ง เพื่อแสดงให้เห็นว่าเครื่องมือเหล่านี้ไม่สามารถแสดงชื่อฟังก์ชันและโครงสร้างโปรแกรมที่อ่านเข้าใจได้เหมือนเดิม</li><li><strong>ทดสอบกับเครื่องมือเฉพาะทาง:</strong> รัน <strong>Redress</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1322" target="_blank" rel="noopener noreferrer">22:02</a>] และ <strong>Go ReSim</strong> [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1374" target="_blank" rel="noopener noreferrer">22:54</a>] กับไฟล์ <code>garbled.exe</code> ซึ่งผลลัพธ์แสดงให้เห็นว่าเครื่องมือเหล่านี้ก็ไม่สามารถดึงข้อมูลที่เป็นประโยชน์ออกมาได้เช่นกัน</li></ol><p><strong>Demo 3: การถอดรหัสข้อความที่ถูกอำพราง</strong></p><ol><li><strong>เตรียมเครื่องมือ:</strong> แสดงการดาวน์โหลด (clone) และติดตั้งเครื่องมือ <strong>Go String Ungarbler</strong> จาก GitHub [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1633" target="_blank" rel="noopener noreferrer">27:13</a>]</li><li><strong>รันคำสั่งถอดรหัส:</strong> ใช้คำสั่ง <code>go_string_ungarbler.py</code> กับไฟล์ <code>garbled.exe</code> เพื่อสั่งให้โปรแกรมถอดรหัสข้อความและบันทึกลงในไฟล์ใหม่ [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1666" target="_blank" rel="noopener noreferrer">27:46</a>]</li><li><strong>แสดงผลลัพธ์:</strong> เปิดไฟล์ผลลัพธ์ (<code>strings_dump.txt</code>) ขึ้นมาโชว์ ซึ่งจะเห็นข้อความ &quot;please subscribe&quot; ถูกถอดรหัสออกมาได้สำเร็จอย่างชัดเจน [<a href="http://www.youtube.com/watch?v=gewnAzaZXQo&amp;t=1695" target="_blank" rel="noopener noreferrer">28:15</a>]</li></ol><p>โดยสรุป คลิปนี้ให้ความรู้ที่ครอบคลุมและทันสมัยเกี่ยวกับการต่อสู้ทางไซเบอร์ในมิติของภาษา Go พร้อมทั้งมีการสาธิตการใช้งานเครื่องมือต่างๆ ให้เห็นภาพจริง ซึ่งเป็นประโยชน์อย่างมากสำหรับผู้ที่สนใจด้านการวิเคราะห์มัลแวร์และวิศวกรรมย้อนกลับ (reverse engineering) ครับ http://googleusercontent.com/youtube_content/1</p>`,14)]])}var c=i(o,[[`render`,s]]);export{a as _pageData,c as default};